steps.script:
$o=@{tasks=@();processes=@();cdp='unknown';logs=@()}
foreach($n in @('TTiTTulares Local','TTendencias Local','TTendencias Local Ready','TT Automation Watchdog')){
 try{$t=Get-ScheduledTask -TaskName $n -ErrorAction Stop;$i=Get-ScheduledTaskInfo -TaskName $n;$o.tasks+=@{name=$n;state=[string]$t.State;last=[string]$i.LastRunTime;result=$i.LastTaskResult}}catch{$o.tasks+=@{name=$n;state='absent'}}
}
try{$p=Get-CimInstance Win32_Process -ErrorAction Stop|Where-Object{$_.Name -in @('powershell.exe','pwsh.exe','node.exe') -and [string]$_.CommandLine -match 'TTiTTularesDedicatedListener|TTendenciasDedicatedListener|TT-LocalWatchdog|TT-AutoUpdater|Ejecutar[.]js|TT-Editorial-Guard'}
foreach($x in $p){$c=[string]$x.CommandLine;$o.processes+=@{kind=$(if($c -match 'TTiTTularesDedicatedListener'){'news_listener'}elseif($c -match 'TTendenciasDedicatedListener'){'trends_listener'}elseif($c -match 'TT-LocalWatchdog'){'watchdog'}elseif($c -match 'TT-AutoUpdater'){'updater'}elseif($c -match 'TT-Editorial-Guard'){'editorial_guard'}else{'editorial_runner'});pid=$x.ProcessId;created=[string]$x.CreationDate}}}catch{}
try{$v=Invoke-RestMethod 'http://127.0.0.1:9223/json/list' -TimeoutSec 5;$o.cdp=@{pages=@($v|Where-Object{$_.type -eq 'page'}).Count;chat=@($v|Where-Object{$_.url -like 'https://chatgpt.com/*'}).Count}}catch{$o.cdp='unreachable'}
foreach($n in @('tt-local-watchdog.log','tt-auto-updater.log','ttittulares-listener.watchdog.err.log','ttendencias-listener.watchdog.err.log')){
 $p=Join-Path 'C:\TTiTTulares' $n
 if(Test-Path $p){$x=Get-Item $p;$o.logs+=@{file=$n;changed=$x.LastWriteTimeUtc.ToString('o');bytes=$x.Length}}
}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress -Depth 5))
